/*
 * A191127  Increasing sequence generated by these rules: a(1)=1, and if x is
 *          in a then 3x and 4x-2 are in a.
 * https://oeis.org/A191127
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 14, u16 n <= 670, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* OEIS A191127: sequence generated by closure of 1 under the rules
   x → 3x and x → 4x-2, sorted in increasing order. */

#include <stdlib.h>
#include <stdbool.h>

/* cache of computed terms */
static seq_t *seq_arr = NULL;
static idx_t seq_len = 0;
static size_t seq_cap = 0;

/* min‑heap for pending values */
static seq_t *heap = NULL;
static size_t heap_size = 0;
static size_t heap_cap = 0;

/* push a value onto the min‑heap */
static void heap_push(seq_t val)
{
    size_t i = heap_size++;
    while (i > 0) {
        size_t parent = (i - 1) >> 1;
        if (heap[parent] <= val) break;
        heap[i] = heap[parent];
        i = parent;
    }
    heap[i] = val;
}

/* pop the smallest value from the min‑heap */
static seq_t heap_pop_min(void)
{
    seq_t min = heap[0];
    seq_t last = heap[--heap_size];
    size_t i = 0;
    while (1) {
        size_t left = (i << 1) + 1;
        if (left >= heap_size) break;
        size_t right = left + 1;
        size_t smallest = left;
        if (right < heap_size && heap[right] < heap[left]) smallest = right;
        if (heap[smallest] >= last) break;
        heap[i] = heap[smallest];
        i = smallest;
    }
    heap[i] = last;
    return min;
}

/* compute the n-th term (1‑based) of the sequence */
seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;           /* undefined for n < 1 */

    /* lazy initialization */
    if (seq_arr == NULL) {
        seq_cap = 64;
        seq_arr = (seq_t*)malloc(seq_cap * sizeof(seq_t));
        seq_len = 0;

        heap_cap = 64;
        heap = (seq_t*)malloc(heap_cap * sizeof(seq_t));
        heap_size = 0;

        heap_push((seq_t)1);                /* seed value */
    }

    while (seq_len < n) {
        seq_t cur = heap_pop_min();

        /* skip duplicates; their children have already been inserted */
        if (seq_len > 0 && cur == seq_arr[seq_len - 1]) {
            continue;
        }

        /* store new term */
        if (seq_len == seq_cap) {
            seq_cap <<= 1;
            seq_arr = (seq_t*)realloc(seq_arr, seq_cap * sizeof(seq_t));
        }
        seq_arr[seq_len++] = cur;

        /* push children 3*cur and 4*cur-2 */
        seq_t child1 = (seq_t)3 * cur;
        if (heap_size == heap_cap) {
            heap_cap <<= 1;
            heap = (seq_t*)realloc(heap, heap_cap * sizeof(seq_t));
        }
        heap_push(child1);

        seq_t child2 = (seq_t)4 * cur - (seq_t)2;
        if (heap_size == heap_cap) {
            heap_cap <<= 1;
            heap = (seq_t*)realloc(heap, heap_cap * sizeof(seq_t));
        }
        heap_push(child2);
    }

    return seq_arr[n - 1];
}
